def show_farm_motion(env, seat=0, stride=6, duration=18):
    frames = list(range(0, len(env.steps), stride))
    if frames[-1] != len(env.steps)-1:
        frames.append(len(env.steps)-1)
    observations = [env.steps[idx][seat].observation for idx in frames]
    player_id = int(observations[0].player)
    farms = [obs.farms[player_id] for obs in observations]
    rows, cols = len(farms[0]['tiles']), len(farms[0]['tiles'][0])

    colors = {
        'LOCKED':'#212d35','EMPTY':'#e6ebee','WHEAT':'#e37d50','STRAWBERRY':'#d86d5c',
        'MELON':'#6491b5','PASTURE':'#4f8ba1','WEED':'#b16f81','OTHER':'#a9aeb8'
    }
    def category(tile):
        if tile == 'LOCKED': return 'LOCKED'
        if tile is None: return 'EMPTY'
        if isinstance(tile, dict):
            kind = tile.get('kind')
            if kind == 'PLANT': return tile.get('crop','OTHER')
            if kind == 'PASTURE': return 'PASTURE'
            if kind == 'WEED': return 'WEED'
        return 'OTHER'

    cell=27; gap=2; map_x=34; map_y=74
    map_w=cols*cell; map_h=rows*cell
    width=960; height=405
    parts=[]
    parts.append(f'<div style="background:#fff;border:1px solid #d6dde2;border-radius:24px;padding:14px 14px 10px;box-shadow:0 10px 28px rgba(26,50,66,.07);margin:14px 0 16px;overflow-x:auto;color:#182732">')
    parts.append(f'<svg viewBox="0 0 {width} {height}" width="100%" style="min-width:760px;max-width:1040px;display:block;margin:auto" xmlns="http://www.w3.org/2000/svg">')
    parts.append('<rect x="8" y="8" width="944" height="389" rx="22" fill="#f7f9fa" stroke="#d6dde2"/>')
    parts.append('<text x="34" y="34" font-size="17" font-weight="800" fill="#182732">Farm topology in motion</text>')
    parts.append('<text x="34" y="54" font-size="11.5" fill="#5e6673">A compressed replay of the full 720-turn season · tiles + farmer + hired hands</text>')

    # phase rail
    phase_x=495; phase_y=35; phase_w=410
    phases=[(0,.17,'BUILD','#2e6286'),(.17,.67,'SCALE','#1d7493'),(.67,.93,'PROTECT','#ad6477'),(.93,1.0,'CLOSE','#b54614')]
    for a,b,label,color in phases:
        x=phase_x+a*phase_w; w=(b-a)*phase_w
        parts.append(f'<rect x="{x:.1f}" y="{phase_y}" width="{w:.1f}" height="7" rx="3.5" fill="{color}" opacity=".72"/>')
        if w>45:
            parts.append(f'<text x="{x+w/2:.1f}" y="{phase_y+22}" text-anchor="middle" font-size="9" font-weight="800" fill="{color}">{label}</text>')
    parts.append(f'<circle cx="{phase_x}" cy="{phase_y+3.5}" r="6" fill="#FFFFFF" stroke="#182732" stroke-width="2"><animate attributeName="cx" values="{phase_x};{phase_x+phase_w}" dur="{duration}s" repeatCount="indefinite"/></circle>')

    # map background and grid
    parts.append(f'<rect x="{map_x-8}" y="{map_y-8}" width="{map_w+16}" height="{map_h+16}" rx="18" fill="#FFFFFF" stroke="#d6dde2"/>')
    nframes=len(frames)
    for r in range(rows):
        for c in range(cols):
            vals=[colors[category(f['tiles'][r][c])] for f in farms]
            x=map_x+c*cell; y=map_y+r*cell
            parts.append(f'<rect x="{x}" y="{y}" width="{cell-gap}" height="{cell-gap}" rx="4" fill="{vals[0]}"><animate attributeName="fill" values="{";".join(vals)}" dur="{duration}s" calcMode="discrete" repeatCount="indefinite"/></rect>')

    # moving farmer
    fx=[]; fy=[]
    for farm in farms:
        rr,cc=farm['farmer']
        fx.append(map_x+cc*cell+(cell-gap)/2); fy.append(map_y+rr*cell+(cell-gap)/2)
    parts.append(f'<circle cx="{fx[0]:.1f}" cy="{fy[0]:.1f}" r="8.8" fill="#FFFFFF" stroke="#182732" stroke-width="3"><animate attributeName="cx" values="{";".join(f"{v:.1f}" for v in fx)}" dur="{duration}s" calcMode="linear" repeatCount="indefinite"/><animate attributeName="cy" values="{";".join(f"{v:.1f}" for v in fy)}" dur="{duration}s" calcMode="linear" repeatCount="indefinite"/></circle>')
    parts.append(f'<circle cx="{fx[0]:.1f}" cy="{fy[0]:.1f}" r="3.2" fill="#2e6286"><animate attributeName="cx" values="{";".join(f"{v:.1f}" for v in fx)}" dur="{duration}s" calcMode="linear" repeatCount="indefinite"/><animate attributeName="cy" values="{";".join(f"{v:.1f}" for v in fy)}" dur="{duration}s" calcMode="linear" repeatCount="indefinite"/></circle>')

    # hired hands
    max_hands=max(len(f['hands']) for f in farms)
    offsets=[(-5,-5),(5,-5),(-5,5),(5,5),(0,-7),(0,7),(-7,0),(7,0)]
    for h in range(max_hands):
        xs=[]; ys=[]; op=[]
        dx,dy=offsets[h%len(offsets)]
        for f in farms:
            if h < len(f['hands']):
                rr,cc=f['hands'][h]
                xs.append(map_x+cc*cell+(cell-gap)/2+dx*.55); ys.append(map_y+rr*cell+(cell-gap)/2+dy*.55); op.append('0.9')
            else:
                xs.append(map_x); ys.append(map_y); op.append('0')
        parts.append(f'<circle cx="{xs[0]:.1f}" cy="{ys[0]:.1f}" r="3.3" fill="#d9eef5" stroke="#1d7493" stroke-width="1.4" opacity="{op[0]}"><animate attributeName="cx" values="{";".join(f"{v:.1f}" for v in xs)}" dur="{duration}s" calcMode="linear" repeatCount="indefinite"/><animate attributeName="cy" values="{";".join(f"{v:.1f}" for v in ys)}" dur="{duration}s" calcMode="linear" repeatCount="indefinite"/><animate attributeName="opacity" values="{";".join(op)}" dur="{duration}s" calcMode="discrete" repeatCount="indefinite"/></circle>')

    # right-side legend / readout
    sx=350
    parts.append(f'<text x="{sx}" y="88" font-size="11" font-weight="800" letter-spacing="1.3" fill="#5e6673">WHAT TO WATCH</text>')
    notes=[('Capacity expands','More cells become productive before the closeout.','#2e6286'),('Labor circulates','White/teal markers reveal routing and service pressure.','#1d7493'),('Weeds are local shocks','Purple cells appear stochastically; repair should stay local.','#b16f81'),('Deadline changes behavior','The final phase converts operating value back to cash.','#b54614')]
    yy=108
    for title,desc,col in notes:
        parts.append(f'<circle cx="{sx+4}" cy="{yy+3}" r="4" fill="{col}"/><text x="{sx+17}" y="{yy+6}" font-size="12.5" font-weight="800" fill="#182732">{html.escape(title)}</text><text x="{sx+17}" y="{yy+24}" font-size="10.5" fill="#5e6673">{html.escape(desc)}</text>')
        yy+=52

    # legend
    parts.append(f'<text x="{sx}" y="317" font-size="10" font-weight="800" letter-spacing="1.2" fill="#5e6673">TILES</text>')
    legend=[('Empty','EMPTY'),('Wheat','WHEAT'),('Strawberry','STRAWBERRY'),('Melon','MELON'),('Pasture','PASTURE'),('Weed','WEED'),('Locked','LOCKED')]
    lx=sx; ly=331
    for i,(label,key) in enumerate(legend):
        col=i%4; row=i//4; x=lx+col*112; y=ly+row*27
        parts.append(f'<rect x="{x}" y="{y-10}" width="13" height="13" rx="3" fill="{colors[key]}"/><text x="{x+19}" y="{y+1}" font-size="10" fill="#546068">{label}</text>')
    parts.append(f'<circle cx="{sx+4}" cy="389" r="6" fill="#fff" stroke="#182732" stroke-width="2"/><text x="{sx+17}" y="393" font-size="10" fill="#546068">Farmer</text><circle cx="{sx+99}" cy="389" r="3.3" fill="#d9eef5" stroke="#1d7493" stroke-width="1.3"/><text x="{sx+111}" y="393" font-size="10" fill="#546068">Hands</text>')
    parts.append('</svg></div>')
    display(HTML(''.join(parts)))

# This is the same direct call used in the diagnostic section: build a live env,
# run the actual agent, then render the replay from env.steps.
TOP_REPLAY_SEED = 70117
env = make(
    "kaggriculture",
    configuration={"episodeSteps": 720, "seed": TOP_REPLAY_SEED},
    debug=False,
)
with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
    env.run([str(_top_agent_path), str(_top_agent_path)])
show_farm_motion(env, seat=0, stride=6, duration=18)

try:
    _top_agent_path.unlink()
except OSError:
    pass
