      <div style="flex:1;min-width:145px;background:#eff7f9;border:1px solid #d6e3e8;border-radius:14px;padding:10px 12px"><div style="font-size:10px;letter-spacing:.11em;font-weight:800;color:#5e6673">AFTER {len(prices)} UNITS</div><div style="font-size:21px;font-weight:850;color:#182732">{money(prices[-1])}</div></div>
      <div style="flex:1;min-width:145px;background:#faf2f4;border:1px solid #ebdadf;border-radius:14px;padding:10px 12px"><div style="font-size:10px;letter-spacing:.11em;font-weight:800;color:#5e6673">{q}-UNIT IMPACT SCORE</div><div style="font-size:21px;font-weight:850;color:#182732">{money(impact_score)}</div></div>
      <div style="flex:1;min-width:145px;background:#fdf1eb;border:1px solid #eecebf;border-radius:14px;padding:10px 12px"><div style="font-size:10px;letter-spacing:.11em;font-weight:800;color:#5e6673">TOTAL REVENUE</div><div style="font-size:21px;font-weight:850;color:#182732">{money(revenue[-1])}</div></div>
    </div>
    <svg viewBox="0 0 {width} {height}" width="100%" style="min-width:760px;max-width:980px;display:block;margin:auto" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" role="img" aria-label="Animated market price erosion and cumulative revenue">
      <defs>
        <linearGradient id="kgPriceGrad" x1="0" x2="1"><stop offset="0" stop-color="#275d82"/><stop offset="1" stop-color="#1d7493"/></linearGradient>
        <linearGradient id="kgRevGrad" x1="0" x2="1"><stop offset="0" stop-color="#1d7493"/><stop offset="1" stop-color="#ad6477"/></linearGradient>
        <filter id="kgGlow"><feGaussianBlur stdDeviation="2" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
      </defs>
      <rect x="18" y="14" width="924" height="334" rx="22" fill="#f7f9fa" stroke="#d6dde2"/>
      <text x="62" y="48" fill="#182732" font-size="17" font-weight="800">Market pressure in motion · {item.title()}</text>
      <text x="62" y="68" fill="#5e6673" font-size="12">The same sale becomes less valuable as shared inventory moves before it.</text>

      <rect x="44" y="78" width="396" height="232" rx="16" fill="#fff" stroke="#d6dde2"/>
      <rect x="522" y="78" width="396" height="232" rx="16" fill="#fff" stroke="#d6dde2"/>
